"""Cross-check actual FreeMote CLI output, independent of our synthetic writer.

Generated by the separately bundled PsBuild.exe (versions 2 and 3), and then
decompiled by PsbDecompile.exe to obtain the expected native JSON. The compiler
adds spec=win. Inputs contain no game data, keys, save states or cached answers.
Generation evidence: analysis/kirikiri-autonomous-20261025/native-psb-probe/.
"""
import base64
import hashlib
import struct
import unittest

import typed_evidence as typed


NATIVE = {
    2: ('7d4e85584c72d8fdcace83e468e6076be08c7f74c7f8de6eadd46e2a72442b8a',
        ''),
    3: ('45ab90067759c5d699021f4fae2862e01195946a359a5dc74067945551e6eafa',
        '')}
EXPECTED = dict(type='generic', rows=[
    dict(scope='chapter_demo', coordinate=7, text='Synthetic dialogue', speaker='Character'),
    dict(scope='chapter_demo', coordinate=8, text='Synthetic dialogue', speaker=None)],
    flags=[True, False, None], numbers=[0, -4, 257, 1.25], spec='win')


def raw(version):
    expected_hash, encoded = NATIVE[version]
    data = base64.b64decode(encoded, validate=True)
    if hashlib.sha256(data).hexdigest() != expected_hash:
        raise AssertionError('Native CLI regression fixture changed')
    return data


def proof(path, kind):
    return dict(kind='typed_field', document=dict(syntax='psb'), path=path, type=kind)


class NativePsbReferenceTests(unittest.TestCase):
    def test_native_v2_v3_match_separate_decompiler_json_exactly(self):
        for version, size in ((2, 544), (3, 560)):
            with self.subTest(version=version):
                data = raw(version)
                self.assertEqual(len(data), size)
                parsed = typed.parse_document(data, dict(syntax='psb'))
                self.assertEqual(typed.plain(parsed['root']), EXPECTED)

    def test_native_false_true_wire_tags_are_not_inverted(self):
        for version in NATIVE:
            data = raw(version)
            first = typed.replay_field(data, proof(['flags', 0], 'boolean'))
            second = typed.replay_field(data, proof(['flags', 1], 'boolean'))
            self.assertIs(first['value'], True)
            self.assertEqual(data[first['span']['offset']], 3)
            self.assertIs(second['value'], False)
            self.assertEqual(data[second['span']['offset']], 2)
            self.assertIsNone(typed.replay_field(data, proof(['flags', 2], 'null'))['value'])

    def test_native_same_text_preserves_two_distinct_message_references(self):
        for version in NATIVE:
            data = raw(version)
            first = typed.replay_field(data, proof(['rows', 0, 'text'], 'string'))
            second = typed.replay_field(data, proof(['rows', 1, 'text'], 'string'))
            self.assertEqual(first['value'], second['value'])
            self.assertEqual(first['node']['string_span'], second['node']['string_span'])
            self.assertNotEqual(first['span']['offset'], second['span']['offset'])

    def test_native_empty_tables_have_zero_element_width_and_exact_alignment(self):
        for version in NATIVE:
            data = raw(version)
            offsets, lengths, payload = struct.unpack_from('<III', data, 24)
            self.assertEqual(data[offsets:lengths], b'\x0d\0\x0c')
            self.assertEqual(data[lengths:lengths+3], b'\x0d\0\x0c')
            self.assertEqual(data[lengths+3:payload], b'\0'*(payload-lengths-3))
            self.assertEqual(payload % 16, 0)
            self.assertTrue(0 < payload-lengths-3 <= 15)

    def test_nonzero_excessive_and_unaligned_padding_are_rejected(self):
        for version in NATIVE:
            data = raw(version)
            lengths, payload = struct.unpack_from('<II', data, 28)
            corrupted = bytearray(data)
            corrupted[lengths+3] = 1
            with self.subTest(version=version, kind='nonzero'), self.assertRaisesRegex(ValueError, 'trailing bytes'):
                typed.parse_document(bytes(corrupted), dict(syntax='psb'))
            excessive = bytearray(data+b'\0'*16)
            struct.pack_into('<I', excessive, 32, payload+16)
            with self.subTest(version=version, kind='excessive'), self.assertRaisesRegex(ValueError, 'trailing bytes'):
                typed.parse_document(bytes(excessive), dict(syntax='psb'))
            unaligned = bytearray(data+b'\0')
            struct.pack_into('<I', unaligned, 32, payload+1)
            with self.subTest(version=version, kind='unaligned'), self.assertRaisesRegex(ValueError, 'trailing bytes'):
                typed.parse_document(bytes(unaligned), dict(syntax='psb'))

    def test_zero_width_arrays_replay_native_count_with_bounded_expansion(self):
        parser = typed._Psb.__new__(typed._Psb)
        parser.data, parser.ranges = b'\x0d\x03\x0c', {}
        self.assertEqual(parser.packed(0, 3), ([0, 0, 0], 3))
        parser.data, parser.ranges = b'\x0f'+(typed.MAX_NODES+1).to_bytes(3, 'little')+b'\x0c', {}
        with self.assertRaises(ValueError):
            parser.packed(0, len(parser.data))
        for tag in (11, 21):
            parser.data, parser.ranges = b'\x0d\0'+bytes([tag]), {}
            with self.assertRaises(ValueError):
                parser.packed(0, 3)


if __name__ == '__main__':
    unittest.main()
